  string AuraUiWriteUnavailableReason(){if(closing)return "正在结束设备连接，请等待操作完成。";if(render)return "此界面仅展示布局，不发送设备设置。";if(!hardwareControlPolicy.Enabled)return HardwareControlPolicy.BlockedMessage;if(busy||AuraSyncBusy)return "设备请求尚未结束，请等待当前操作完成。";return null;}
  string AuraApplyUnavailableReason(){
   var reason=AuraUiWriteUnavailableReason();if(reason!=null)return reason;
   if(auraSyncSelected.Count==0)return "请在同步设备中读取并勾选具有可用灯光接口的设备。";
   var chosen=auraSyncTargets.Where(t=>auraSyncSelected.Contains(t.Id)).ToArray();
   if(chosen.Length!=auraSyncSelected.Count||chosen.Any(t=>!AuraBindingCurrent(t)))return "所选设备尚无本次连接的灯光读取结果，请重新扫描。";
   var unavailable=chosen.FirstOrDefault(t=>!t.Online||!t.CanStaticRgb);if(unavailable!=null)return unavailable.UnavailableReason??"所选设备的灯光接口尚未确认，请重新扫描。";
   return effect=="static"||effect=="off"||AuraAnimationPhase.SupportsUniform(effect)?null:"此灯效的写入接口尚未接通。";
  }
  string AuraOwnershipUnavailableReason(AuraSyncTarget target){var reason=AuraUiWriteUnavailableReason();return reason??(!AuraBindingCurrent(target)?"原灯光连接已失效，请重新扫描后再确认控制归属。":null);}
  static string AuraDeviceAvailabilityLabel(AuraSyncTarget target){if(target==null)return "不可用";if((target.Backend=="direct"||target.Backend=="gear")&&target.WorkerSession==null)return "待读取";if(!target.Online)return "未在线";if(target.CanStaticRgb)return target.PhysicalWriteValidated?"可同步":"待验证";return target.CanReleaseSoftwareLighting?"待接管":"不可用";}
  static string AuraDeviceAvailabilityDetail(AuraSyncTarget target){if(target==null)return "设备状态尚未确认。";if((target.Backend=="direct"||target.Backend=="gear")&&target.WorkerSession==null)return "新会话尚未读取此设备的灯光状态；旧配置不作为当前可用状态，请重新扫描。";if(target.CanStaticRgb&&!target.PhysicalWriteValidated)return "已读取可提交的颜色接口，尚未完成此设备的实际灯光写入验证；勾选与参数调整只编辑草稿，点击应用同步才提交。";return target.UnavailableReason;}
  string AuraAnimationStatusLabel(){var report=auraAnimation==null?null:auraAnimation.Report;if(report==null||report.State=="preparing"||auraAnimationPreparationTask!=null&&!auraAnimationPreparationTask.IsCompleted)return "正在核对灯光…";if(report.State=="faulted"||report.State=="stopped"||report.State=="stopping")return "同步已停止";if(report.Frames==0)return "等待首帧结果…";return report.AllLastFrameReadbackConfirmed?"软件同步运行中 · 配置已读回":"软件同步运行中 · 灯光读回未确认";}
  void OriginalAuraOperationStatus(StackPanel target){if(String.IsNullOrWhiteSpace(auraSyncMessage))return;string summary="",detail=auraSyncMessage;if(AuraAnimationActive){summary=AuraAnimationStatusLabel();if(auraAnimation!=null){var report=auraAnimation.Report;detail+="\n已提交帧："+report.Frames+"；最近一轮提交跨度："+report.LastDispatchSkewMilliseconds+" ms（非硬件时序读回）。\n实际刷新率："+report.ObservedFramesPerSecond.ToString("0.##")+" fps；整体颜色读回确认："+(report.AllLastFrameReadbackConfirmed?"是":"否");}}else if(auraSyncBusy)summary="正在读取…";else if(auraSyncResult!=null&&auraSyncResult.Devices!=null){int confirmed=auraSyncResult.Devices.Count(d=>d.ReadbackConfirmed);int failed=auraSyncResult.Devices.Count(d=>d.State=="failed"||d.State=="preflightFailed");summary=confirmed+" 项配置已确认"+(failed>0?" · "+failed+" 项失败":"");}else if(auraSyncMessage.Contains("未完成")||auraSyncMessage.Contains("未确认")||auraSyncMessage.Contains("失败")||auraSyncMessage.Contains("已停止"))summary="同步已停止";if(summary.Length>0){var statusText=Label(summary,12,muted);statusText.Tag="aura-operation-status";statusText.ToolTip=detail;statusText.Margin=new Thickness(0,8,0,14);target.Children.Add(statusText);}}
  UIElement OriginalAuraDeviceCard(AuraSyncTarget target){var surface=new Grid{Tag=target.Id,Height=235,Margin=new Thickness(0,0,14,14),Background=Brush("#1C1C1C")};surface.RowDefinitions.Add(new RowDefinition{Height=new GridLength(126)});surface.RowDefinitions.Add(new RowDefinition{Height=new GridLength(48)});surface.RowDefinitions.Add(new RowDefinition{Height=new GridLength(35)});surface.RowDefinitions.Add(new RowDefinition());var icon=OriginalAuraDeviceIcon(target.Kind,target.Online?text:muted);icon.HorizontalAlignment=HorizontalAlignment.Center;icon.VerticalAlignment=VerticalAlignment.Bottom;icon.Margin=new Thickness(0,0,13,12);surface.Children.Add(icon);var check=new CheckBox{IsChecked=target.CanStaticRgb&&target.Online&&auraSyncSelected.Contains(target.Id),IsEnabled=target.CanStaticRgb&&target.Online&&!busy&&!AuraSyncBusy,Margin=new Thickness(22,21,0,0),HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Top,Foreground=text,Template=AuraSelectionTemplate()};check.Checked+=(s,e)=>{if(!busy&&!AuraSyncBusy&&target.CanStaticRgb&&target.Online)auraSyncSelected.Add(target.Id);};check.Unchecked+=(s,e)=>{if(!busy&&!AuraSyncBusy)auraSyncSelected.Remove(target.Id);};check.ToolTip=target.CanStaticRgb&&target.Online?"勾选只选择设备；点击应用同步后才提交灯光设置。":AuraDeviceAvailabilityDetail(target);ToolTipService.SetShowOnDisabled(check,true);surface.Children.Add(check);var name=Paragraph(target.Name??"—",14,text);name.LineHeight=21;name.TextAlignment=TextAlignment.Center;name.Margin=new Thickness(14,8,14,0);Grid.SetRow(name,1);surface.Children.Add(name);string route=target.Kind=="keyboard"||target.Kind=="mouse"||target.Kind=="headset"||target.Kind=="fan"?target.Kind:null;if(route!=null){var link=Button("设置设备灯光",()=>OpenOriginalDevice(route));link.Background=Brushes.Transparent;link.BorderThickness=new Thickness(0);link.Padding=new Thickness(2);link.FontSize=11;link.Margin=new Thickness(0);link.HorizontalAlignment=HorizontalAlignment.Center;Grid.SetRow(link,2);surface.Children.Add(link);}AuraOwnershipResult ownership;var result=auraSyncResult==null||auraSyncResult.Devices==null?null:auraSyncResult.Devices.FirstOrDefault(d=>d.TargetId==target.Id);string state=result!=null?(result.ReadbackConfirmed?"配置已读回":"未确认"):AuraDeviceAvailabilityLabel(target);if(auraOwnershipResults.TryGetValue(target.Id,out ownership)&&!ownership.OwnershipConfirmed&&ownership.State!="returned")state=ownership.RestorationConfirmed?"接管未完成":"恢复未确认";var stateText=Label(state,11,result!=null&&result.ReadbackConfirmed||target.CanStaticRgb&&target.PhysicalWriteValidated?green:muted);stateText.Tag="aura-target-state:"+target.Id;stateText.TextAlignment=TextAlignment.Center;stateText.Margin=new Thickness(10,0,10,4);stateText.ToolTip=result!=null?AuraSyncResultLabel(result):ownership!=null?ownership.Error:AuraDeviceAvailabilityDetail(target);Grid.SetRow(stateText,3);surface.Children.Add(stateText);var line=new Border{Height=2,VerticalAlignment=VerticalAlignment.Bottom,Background=new LinearGradientBrush{StartPoint=new Point(0,0),EndPoint=new Point(1,0),GradientStops=new GradientStopCollection{new GradientStop(Color.FromRgb(115,208,120),0),new GradientStop(Color.FromRgb(73,112,224),0.35),new GradientStop(Color.FromRgb(183,57,212),0.7),new GradientStop(Color.FromRgb(221,39,65),1)}}};Grid.SetRowSpan(line,4);surface.Children.Add(line);return surface;}
  Canvas OriginalAuraDeviceIcon(string kind,Brush ink){var icon=new Canvas{Width=74,Height=74};if(kind=="motherboard"){AuraRect(icon,10,7,53,60,ink);AuraRect(icon,20,18,20,20,ink);for(int i=0;i<3;i++)AuraLine(icon,48+i*5,17,48+i*5,46,ink);AuraLine(icon,17,48,42,48,ink);AuraLine(icon,17,57,42,57,ink);}else if(kind=="keyboard"){AuraRect(icon,5,17,64,43,ink);for(int row=0;row<3;row++)for(int col=0;col<6;col++)AuraRect(icon,11+col*9,25+row*9,5,5,ink);}else if(kind=="mouse"){var outline=new Path{Stroke=ink,StrokeThickness=3,Data=Geometry.Parse("M 37,5 C 16,5 15,22 15,36 L 15,48 C 15,75 59,75 59,48 L 59,36 C 59,22 58,5 37,5 Z")};icon.Children.Add(outline);AuraLine(icon,37,6,37,28,ink);AuraLine(icon,16,28,58,28,ink);}else if(kind=="headset"){icon.Children.Add(new Path{Stroke=ink,StrokeThickness=3,Data=Geometry.Parse("M 12,43 L 12,31 C 12,0 62,0 62,31 L 62,43")});AuraRect(icon,9,35,12,28,ink);AuraRect(icon,53,35,12,28,ink);}else if(kind=="gpu"||kind=="fan"){AuraRect(icon,4,18,66,42,ink);for(int i=0;i<3;i++)AuraCircle(icon,17+i*20,39,7,ink,false);AuraLine(icon,10,66,23,66,ink);}else if(kind=="dram"){AuraRect(icon,7,27,60,25,ink);for(int i=0;i<7;i++)AuraLine(icon,13+i*7,54,13+i*7,62,ink);}else{AuraRect(icon,12,12,50,50,ink);AuraLine(icon,23,25,51,25,ink);AuraLine(icon,23,36,51,36,ink);AuraLine(icon,23,47,45,47,ink);}return icon;}
