namespace RogControl {
 public sealed class AuraSyncNativeReply {
  public int id;public bool ok,controlled;public object error;public System.Collections.Generic.List<System.Collections.Generic.Dictionary<string,object>> devices;public string[] warnings;
 }
 public partial class MainWindow {
  readonly AuraSyncCoordinator auraSyncCoordinator=new AuraSyncCoordinator();
  readonly List<AuraSyncTarget> auraSyncTargets=new List<AuraSyncTarget>();
  readonly HashSet<string> auraSyncSelected=new HashSet<string>(StringComparer.Ordinal);
  AuraSyncResult auraSyncResult;
  bool auraSyncBusy,auraSyncConnectionsActive,auraSyncStopRequested;
  readonly Dictionary<string,AuraOwnershipResult> auraOwnershipResults=new Dictionary<string,AuraOwnershipResult>(StringComparer.Ordinal);
  string auraSyncMessage="";
  public bool AuraSyncBusy {get{return auraSyncBusy||auraSyncCoordinator.Running||AuraAnimationActive||auraStopTask!=null&&!auraStopTask.IsCompleted;}}
  public bool AuraSyncConnectionsActive {get{return auraSyncConnectionsActive;}}

  System.Threading.Tasks.Task ScanAllAuraTargetsAsync(){if(busy||AuraSyncBusy||closing||render)return System.Threading.Tasks.Task.FromResult(0);auraScanTask=ScanAllAuraTargetsCoreAsync();return auraScanTask;}
  async System.Threading.Tasks.Task ScanAllAuraTargetsCoreAsync() {
   if(busy||AuraSyncBusy||closing||render)return;busy=true;auraSyncBusy=true;auraSyncStopRequested=false;auraSyncMessage="正在读取各设备的灯效能力…";auraSyncTargets.Clear();auraSyncResult=null;ShowPage(page);
   try {
    try {
     long generation=DeviceHotplugGeneration;var native=await worker.Request<AuraSyncNativeReply>(new Dictionary<string,object>{{"op","scan"}});
     if(!native.ok)throw new InvalidOperationException(SdkError(native.error));
     foreach(var device in native.devices??new List<Dictionary<string,object>>())auraSyncTargets.Add(BindAuraTarget(AuraSyncCoordinator.Direct(device,info.Board,DateTime.UtcNow),worker.SessionIdentity,generation));
     if((native.devices??new List<Dictionary<string,object>>()).Count==0)auraSyncTargets.Add(AuraSyncCoordinator.Missing("motherboard",info.Board,"未读到主板 RGB 控制接口。",DateTime.UtcNow));
    }catch(Exception ex){auraSyncTargets.Add(AuraSyncCoordinator.Missing("motherboard",info.Board,"主板灯控读取失败："+ex.GetBaseException().Message,DateTime.UtcNow));}
    foreach(string kind in new[]{"keyboard","mouse","headset"}) {
     if(auraSyncStopRequested||closing)break;
     auraSyncMessage="正在读取 "+AuraSyncKindName(kind)+" 灯效能力…";if(page=="灯效 & Aura Sync")ShowPage(page);
     try {
      long generation=DeviceHotplugGeneration;var reply=await gearWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","enumerate"},{"kind",kind}});
      if(!reply.ok)throw new InvalidOperationException(SdkError(reply.error));var list=GearArray(reply.data,"devices");object scanSession=gearWorker.SessionIdentity;
      if(list==null)throw new InvalidOperationException("设备接口未返回完整列表。");
      if(list.Length>64||scanSession==null)throw new InvalidOperationException("设备数量或读取会话无效。");var kindClock=System.Diagnostics.Stopwatch.StartNew();
      if(list.Length==0)auraSyncTargets.Add(AuraSyncCoordinator.Missing(kind,AuraSyncKindName(kind),"未找到此型号的有线或 2.4GHz 控制接口。",DateTime.UtcNow));
      foreach(var raw in list){if(auraSyncStopRequested||closing)break;var descriptor=raw as Dictionary<string,object>;string deviceId=OriginalStateText(descriptor,"deviceId","");if(descriptor==null||deviceId.Length==0||deviceId.Length>128)throw new InvalidOperationException("设备身份数据无效。");int remaining=90000-(int)kindClock.ElapsedMilliseconds;if(remaining<=0)throw new TimeoutException("部分设备尚未读取，请重新扫描。");
       try{var read=await gearWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","lightingRead"},{"kind",kind},{"deviceId",deviceId}},scanSession,Math.Min(18000,remaining),()=>{if(auraSyncStopRequested||closing||render)throw new OperationCanceledException();if(generation!=DeviceHotplugGeneration)throw new InvalidOperationException("设备连接已变化。");});if(!read.ok||read.data==null||OriginalStateText(read.data,"deviceId","")!=deviceId)throw new InvalidOperationException(SdkError(read.error));auraSyncTargets.Add(BindAuraTarget(AuraSyncCoordinator.Gear(read.data,DateTime.UtcNow),scanSession,generation));}
       catch(Exception error){var missing=AuraSyncCoordinator.Missing(kind,OriginalStateText(descriptor,"model",AuraSyncKindName(kind)),"读取失败："+error.GetBaseException().Message,DateTime.UtcNow);missing.Id="unavailable:"+kind+":"+deviceId;missing.DeviceId=deviceId;auraSyncTargets.Add(missing);if(!Object.ReferenceEquals(scanSession,gearWorker.SessionIdentity)||generation!=DeviceHotplugGeneration)break;}
      }
     }catch(Exception ex){auraSyncTargets.Add(AuraSyncCoordinator.Missing(kind,AuraSyncKindName(kind),"读取失败："+ex.GetBaseException().Message,DateTime.UtcNow));}
    }
    if(!auraSyncStopRequested&&!closing)try {
     var scan=await Sdk("fan").Request<SdkReply>(new Dictionary<string,object>{{"op","scan"},{"kind","fan"}});if(!scan.ok)throw new InvalidOperationException(SdkError(scan.error));
     var reply=await Sdk("fan").Request<SdkReply>(new Dictionary<string,object>{{"op","read"},{"kind","fan"},{"deviceId","7576"}});if(!reply.ok||reply.data==null)throw new InvalidOperationException(SdkError(reply.error));auraSyncTargets.Add(AuraSyncCoordinator.Fan(reply.data,DateTime.UtcNow));
    }catch(Exception ex){auraSyncTargets.Add(AuraSyncCoordinator.Missing("fan","ROG EURUX Controller","读取失败："+ex.GetBaseException().Message,DateTime.UtcNow));}
    if(!auraSyncStopRequested&&!closing)try {
     var reply=await discoveryWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","scan"}});if(!reply.ok||OriginalStateFlag(reply.data,"identificationOnly")!=true)throw new InvalidOperationException(SdkError(reply.error));
     var list=GearArray(reply.data,"devices");if(list==null)throw new InvalidOperationException("Windows 设备列表缺失。");
     foreach(var raw in list){var identity=raw as Dictionary<string,object>;if(DiscoveryEntryValid(identity)&&!AuraSyncIdentityRepresented(identity))auraSyncTargets.Add(AuraSyncCoordinator.Identified(identity,DateTime.UtcNow));}
    }catch(Exception ex){auraSyncMessage="其他设备识别未完成："+ex.GetBaseException().Message;}
    foreach(var target in auraSyncTargets.Where(t=>t.Backend=="direct"||t.Backend=="gear"))if(!AuraBindingCurrent(target)){target.Online=false;target.CanStaticRgb=false;target.CanReleaseSoftwareLighting=false;target.UnavailableReason="读取期间设备连接已变化，请重新扫描。";}
    auraSyncSelected.RemoveWhere(id=>!auraSyncTargets.Any(target=>target.Id==id&&target.CanStaticRgb&&target.Online));
    if(auraSyncSelected.Count==0&&!auraSyncStopRequested)foreach(var target in auraSyncTargets.Where(target=>target.CanStaticRgb&&target.Online))auraSyncSelected.Add(target.Id);
    if(auraSyncStopRequested){foreach(var target in auraSyncTargets){target.Online=false;target.CanStaticRgb=false;target.UnavailableReason="连接已释放，请重新扫描。";}auraSyncSelected.Clear();auraSyncMessage="读取已停止。";}
    else auraSyncMessage="可提交 "+auraSyncTargets.Count(target=>target.CanStaticRgb)+" 项 · 已识别 "+auraSyncTargets.Count+" 项；实际灯光仍需验证。";
   }finally{auraSyncBusy=false;busy=false;if(!closing)ShowPage(page);}
  }
  bool AuraSyncIdentityRepresented(IDictionary<string,object> identity) {
   string pid=DiscoveryText(identity,"pid"),name=DiscoveryText(identity,"name");
   if(!DiscoverySignatureKnown(pid,name,String.Equals(info.Board,"ROG CROSSHAIR X870E EXTREME",StringComparison.OrdinalIgnoreCase)))return false;
   if(pid=="1D98")return auraSyncTargets.Any(target=>target.Kind=="fan"&&target.Backend=="sdk");
   if(pid=="1D41")return auraSyncTargets.Any(target=>target.Kind=="headset"&&target.Backend=="gear");
   int productId;if(Int32.TryParse(pid,System.Globalization.NumberStyles.HexNumber,System.Globalization.CultureInfo.InvariantCulture,out productId)&&GearLinkLightingModelFacts.Supports(productId))return auraSyncTargets.Any(target=>target.Backend=="gear"&&OriginalStateText(target.State,"pid","")==productId.ToString(System.Globalization.CultureInfo.InvariantCulture));
   if(pid=="1AA6")return auraSyncTargets.Any(target=>target.Backend=="direct"&&OriginalStateText(target.State,"productId","")==pid);
   return false;
  }
  async System.Threading.Tasks.Task<AuraSyncTarget> RefreshAuraSyncTarget(AuraSyncTarget target) {
   DemandAuraReadBinding(target);object session=target.WorkerSession;long generation=target.ConnectionGeneration;
   if(target.Backend=="direct") {
    var reply=await worker.Request<AuraSyncNativeReply>(new Dictionary<string,object>{{"op","scan"}},session,12000,()=>DemandAuraReadBinding(target));if(!reply.ok)throw new InvalidOperationException(SdkError(reply.error));if(!AuraBindingCurrent(target))throw new InvalidOperationException("灯控连接已变化。");
    var found=(reply.devices??new List<Dictionary<string,object>>()).FirstOrDefault(item=>OriginalStateText(item,"id","")==target.DeviceId);if(found==null)throw new InvalidOperationException("此主板灯控已断开。");return BindAuraTarget(AuraSyncCoordinator.Direct(found,info.Board,DateTime.UtcNow),session,generation);
   }
   if(target.Backend=="gear") {
    var reply=await gearWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","lightingRead"},{"kind",target.Kind},{"deviceId",target.DeviceId}},session,18000,()=>DemandAuraReadBinding(target));if(!reply.ok||reply.data==null)throw new InvalidOperationException(SdkError(reply.error));if(!AuraBindingCurrent(target))throw new InvalidOperationException("灯控连接已变化。");return BindAuraTarget(AuraSyncCoordinator.Gear(reply.data,DateTime.UtcNow),session,generation);
   }
   throw new InvalidOperationException("此设备没有已验证的静态颜色写入接口。");
  }
  async System.Threading.Tasks.Task<AuraSyncCommandReply> SendAuraSyncCommand(AuraSyncCommand command) {
   // Recheck permission at the transport boundary, even when caller validated it.
   DemandAuraCommandBinding(command);
   if(command.Backend=="direct") {
    var reply=await worker.Request<AuraSyncNativeReply>(new Dictionary<string,object>(command.Request),command.ExpectedSession,8000,()=>DemandAuraCommandBinding(command));if(command.ConnectionGeneration!=DeviceHotplugGeneration||!Object.ReferenceEquals(command.ExpectedSession,worker.SessionIdentity))throw new InvalidOperationException("灯控提交后连接已变化，结果未确认。");return new AuraSyncCommandReply{Ok=reply.ok,Accepted=reply.ok,WriteAttempted=true,WriteConfirmed=false,Error=reply.ok?null:SdkError(reply.error)};
   }
   if(command.Backend=="gear") {
    var request=new Dictionary<string,object>(command.Request);if(command.Setting=="staticLighting"&&(command.Kind=="mouse"||command.Kind=="keyboard"||command.Kind=="headset"))request["op"]="lightingSet";var reply=await gearWorker.Request<SdkReply>(request,command.ExpectedSession,18000,()=>DemandAuraCommandBinding(command));if(command.ConnectionGeneration!=DeviceHotplugGeneration||!Object.ReferenceEquals(command.ExpectedSession,gearWorker.SessionIdentity))throw new InvalidOperationException("灯控提交后连接已变化，结果未确认。");if(!reply.ok)return new AuraSyncCommandReply{Ok=false,WriteAttempted=true,Error=SdkError(reply.error)};
    // Scoped lighting replies do not replace a full settings snapshot or silently
    // enable controls on a different page. That page obtains its own full read.
    gearReadSessions.Remove(command.Kind);
    return new AuraSyncCommandReply{Ok=true,Accepted=OriginalStateFlag(reply.data,"accepted")==true,WriteAttempted=OriginalStateFlag(reply.data,"writeAttempted")==true,WriteConfirmed=OriginalStateFlag(reply.data,"writeConfirmed")==true};
   }
   throw new InvalidOperationException("此同步后端尚未接通。");
  }
  void DemandAuraReadBinding(AuraSyncTarget target){if(render||!auraReturningOwnership&&(auraSyncStopRequested||closing))throw new OperationCanceledException("同步已停止。");if(!AuraBindingCurrent(target))throw new InvalidOperationException("灯控连接已变化，请重新扫描。");}
  void DemandAuraCommandBinding(AuraSyncCommand command){hardwareControlPolicy.Demand();bool returning=command!=null&&command.IsOwnershipReturn&&command.Backend=="gear"&&(command.Kind=="mouse"||command.Kind=="keyboard")&&command.Setting=="lightingSoftwareMode"&&command.Request!=null&&OriginalStateFlag(command.Request,"value")==true;if(render||(!returning||!auraReturningOwnership)&&(closing||auraSyncStopRequested))throw new OperationCanceledException("同步已停止。");if(command==null||command.ExpectedSession==null||command.ConnectionGeneration!=DeviceHotplugGeneration||DeviceHotplugPageReadsPaused)throw new InvalidOperationException("灯控写入绑定已失效。");object current=command.Backend=="direct"?worker.SessionIdentity:command.Backend=="gear"?gearWorker.SessionIdentity:null;if(!Object.ReferenceEquals(current,command.ExpectedSession))throw new InvalidOperationException("灯控工作进程已变化。");if(returning&&auraReturningOwnership){AuraOwnershipResult receipt;if(!auraOwnershipResults.TryGetValue(command.TargetId,out receipt)||receipt==null||!receipt.CanReturnOriginalFlag||!receipt.OwnershipConfirmed||receipt.Target==null||receipt.Target.DeviceId!=OriginalStateText(command.Request,"deviceId","")||!Object.ReferenceEquals(receipt.WorkerSession,command.ExpectedSession)||receipt.ConnectionGeneration!=command.ConnectionGeneration)throw new InvalidOperationException("原接管凭据已失效。");}}
  async System.Threading.Tasks.Task ApplyAllAuraTargetsAsync() {
   if(busy||AuraSyncBusy||closing||render)return;if(!PermitHardwareWrite())return;
   busy=true;auraSyncBusy=true;auraSyncStopRequested=false;auraSyncMessage="正在核对所选设备…";ShowPage(page);
   try {
    if(AuraAnimationPhase.SupportsUniform(effect)){auraSyncResult=null;await StartAuraAnimationAsync();return;}
    var operation=auraSyncCoordinator.ApplyAsync(auraSyncTargets,auraSyncSelected,effect,color,brightness,RefreshAuraSyncTarget,SendAuraSyncCommand,()=>{hardwareControlPolicy.Demand();if(closing||render||auraSyncStopRequested)throw new OperationCanceledException("同步已停止。");});auraSyncOperationTask=operation;try{auraSyncResult=await operation;}finally{if(Object.ReferenceEquals(auraSyncOperationTask,operation))auraSyncOperationTask=null;}
    auraSyncConnectionsActive=!auraSyncStopRequested&&(auraSyncConnectionsActive||auraSyncResult.Devices.Any(result=>result.WriteAttempted));controlling=auraSyncConnectionsActive;
    int confirmed=auraSyncResult.Devices.Count(result=>result.ReadbackConfirmed),unconfirmed=auraSyncResult.Devices.Count(result=>result.State=="submittedUnconfirmed"||result.State=="unconfirmed"),failed=auraSyncResult.Devices.Count(result=>result.State=="failed"||result.State=="preflightFailed");
    auraSyncMessage="所选设备："+confirmed+" 项配置读回确认，"+unconfirmed+" 项未确认，"+failed+" 项失败。实体灯光效果需要观察确认。";Log(auraSyncMessage);
   }catch(Exception ex){auraSyncMessage="同步未完成："+ex.GetBaseException().Message;Log(auraSyncMessage);}
   finally{auraSyncBusy=false;busy=false;if(!closing)ShowPage(page);}
  }
  async System.Threading.Tasks.Task TakeAuraSoftwareLightingAsync(AuraSyncTarget target) {
   if(busy||AuraSyncBusy||closing||render)return;if(!PermitHardwareWrite())return;busy=true;auraSyncBusy=true;auraSyncStopRequested=false;auraSyncMessage="正在接管灯效…";ShowPage(page);
   try {
    var operation=auraSyncCoordinator.TakeSoftwareLightingAsync(target,RefreshAuraSyncTarget,SendAuraSyncCommand,()=>{hardwareControlPolicy.Demand();if(closing||render||auraSyncStopRequested)throw new OperationCanceledException("接管已停止。");});auraSyncOperationTask=operation;AuraOwnershipResult result;try{result=await operation;}finally{if(Object.ReferenceEquals(auraSyncOperationTask,operation))auraSyncOperationTask=null;}auraOwnershipResults[target.Id]=result;
    if(result.Target!=null&&result.Target.Id==target.Id){int index=auraSyncTargets.FindIndex(value=>value.Id==target.Id);if(index>=0)auraSyncTargets[index]=result.Target;if(result.OwnershipConfirmed&&result.Target.CanStaticRgb)auraSyncSelected.Add(target.Id);else auraSyncSelected.Remove(target.Id);}
    if(!result.OwnershipConfirmed&&result.Target!=null){result.Target.CanStaticRgb=false;result.Target.UnavailableReason=result.Error+"；原标志恢复："+result.RestorationState;}
    auraSyncConnectionsActive=!auraSyncStopRequested&&(auraSyncConnectionsActive||result.WriteAttempted);controlling=auraSyncConnectionsActive;
    auraSyncMessage=result.OwnershipConfirmed?"灯效接管已读回，可以选择同步。":result.RestorationConfirmed?"接管未完成，原灯控标志已恢复。":"接管未完成，恢复状态未确认。";Log(auraSyncMessage+(String.IsNullOrEmpty(result.Error)?"":" "+result.Error));
   }catch(Exception ex){auraSyncMessage="接管未完成："+ex.GetBaseException().Message;Log(auraSyncMessage);}finally{auraSyncBusy=false;busy=false;if(!closing)ShowPage(page);}
  }
  System.Threading.Tasks.Task StopAllAuraTargetsAsync() {
   RequestAuraAnimationStop();if(auraStopTask==null||auraStopTask.IsCompleted)auraStopTask=StopAuraSyncCoreAsync();return auraStopTask;
  }
  async System.Threading.Tasks.Task ReturnAuraSoftwareLightingAsync(string id) {
   if(busy||AuraSyncBusy||closing||render)return;if(!PermitHardwareWrite())return;AuraOwnershipResult original;if(!auraOwnershipResults.TryGetValue(id,out original)||!original.CanReturnOriginalFlag)return;if(original.Target==null||original.WorkerSession==null||!Object.ReferenceEquals(original.WorkerSession,original.Target.WorkerSession)||original.ConnectionGeneration!=original.Target.ConnectionGeneration||!AuraBindingCurrent(original.Target)){auraSyncMessage="原接管连接已失效，未写入任何恢复设置。";return;}busy=true;auraSyncBusy=true;auraSyncStopRequested=false;auraSyncMessage="正在交还灯效…";ShowPage(page);
   try {
    var operation=auraSyncCoordinator.ReturnSoftwareLightingAsync(original,RefreshAuraSyncTarget,SendAuraSyncCommand,()=>{hardwareControlPolicy.Demand();if(closing||render||auraSyncStopRequested)throw new OperationCanceledException("交还已停止。");});auraSyncOperationTask=operation;AuraOwnershipResult result;try{result=await operation;}finally{if(Object.ReferenceEquals(auraSyncOperationTask,operation))auraSyncOperationTask=null;}
    if(result.RestorationConfirmed)auraOwnershipResults[id]=result;else{original.Error=result.Error;original.RestorationState=result.RestorationState;}
    if(result.Target!=null&&result.Target.Id==id){int index=auraSyncTargets.FindIndex(value=>value.Id==id);if(index>=0)auraSyncTargets[index]=result.Target;}auraSyncSelected.Remove(id);
    if(!result.RestorationConfirmed&&result.Target!=null){result.Target.CanStaticRgb=false;result.Target.UnavailableReason=result.Error;}
    auraSyncConnectionsActive=!auraSyncStopRequested&&(auraSyncConnectionsActive||result.WriteAttempted);controlling=auraSyncConnectionsActive;
    auraSyncMessage=result.RestorationConfirmed?"原软件灯控标志已交还并读回。":"交还未确认，请查看设备状态。";Log(auraSyncMessage+(String.IsNullOrEmpty(result.Error)?"":" "+result.Error));
   }catch(Exception ex){auraSyncMessage="交还未完成："+ex.GetBaseException().Message;Log(auraSyncMessage);}finally{auraSyncBusy=false;busy=false;if(!closing)ShowPage(page);}
  }
  static string AuraSyncKindName(string kind){return kind=="keyboard"?"ROG AZOTH EXTREME EDITION 20":kind=="mouse"?"ROG HARPE II EXTREME EDITION 20":kind=="headset"?"ROG DELTA II-KJP":kind;}
  static string AuraSyncResultLabel(AuraSyncTargetResult result){return result.State=="readbackConfirmed"?"颜色配置已读回；实体效果待确认。":result.State=="submittedUnconfirmed"?"请求已提交，灯光读回未确认。":result.State=="cancelled"?"已停止。":String.IsNullOrEmpty(result.Error)?"未完成。":result.Error;}
 }
